def test_fx_rates_boundary(self):
    def build(n):
        # n entries in total: n-1 unreferenced currencies plus USD.
        rates = {f"C{i}": 1.0 + i * 1e-12 for i in range(n - 1)}
        rates["USD"] = 1.0
        return {
